package com.daniil.wristlens.wear;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import com.daniil.wristlens.shared.*;import org.json.*;import java.util.*;import java.util.function.*;import java.util.concurrent.atomic.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class GallerySettingsTest {
 Activity activity;FakeMedia media;Gallery gallery;
 static List<View> views(View v){List<View> result=new ArrayList<>();result.add(v);if(v instanceof ViewGroup g)for(int i=0;i<g.getChildCount();i++)result.addAll(views(g.getChildAt(i)));return result;}
 static List<View> views(Dialog d){return views(d.getWindow().getDecorView());}
 static TextView text(Dialog d,String label){return (TextView)views(d).stream().filter(v->v instanceof TextView t&&t.getText().toString().equals(label)).findFirst().orElseThrow(()->new AssertionError("Missing: "+label));}
 static boolean has(Dialog d,String label){return views(d).stream().anyMatch(v->v instanceof TextView t&&t.getText().toString().equals(label));}
 @Before public void before(){activity=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(activity);media=new FakeMedia(activity);gallery=new Gallery(activity,media);DownloadTestDispatch.install(activity);}
 @After public void after(){DownloadTestDispatch.restore();gallery.destroy();media.close();for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();activity.finish();}
 static class FakeMedia extends MediaClient {
  List<JSONObject> entries=new ArrayList<>();JSONObject last;String ticket="";int listCalls;String thumb;boolean failCopy;int copies;
  FakeMedia(Context c){super(c,()->"node",e->{throw new AssertionError(e);});entries.add(Wire.object("id","1","name","IMG_one.jpg","mime","image/jpeg"));entries.add(Wire.object("id","2","name","VID_two.mp4","mime","video/mp4"));Bitmap b=Bitmap.createBitmap(2,2,Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream o=new java.io.ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,o);thumb=android.util.Base64.encodeToString(o.toByteArray(),0);b.recycle();}
  @Override void request(JSONObject j,Consumer<JSONObject> done,Consumer<String> fail){last=j;switch(j.optString("op")){case "list"->{listCalls++;done.accept(Wire.object("items",new JSONArray(entries),"cursor",2));}case "thumb"->done.accept(Wire.object("jpeg",thumb));case "delete"->{entries.removeIf(e->e.optString("id").equals(j.optString("id")));done.accept(new JSONObject());}case "delete_many"->{JSONArray ids=j.optJSONArray("ids");entries.removeIf(e->{for(int i=0;i<ids.length();i++)if(ids.optString(i).equals(e.optString("id")))return true;return false;});done.accept(Wire.object("deleted",ids,"errors",new JSONArray()));}case "share"->done.accept(Wire.object("token","share-ticket"));default->fail.accept("unexpected "+j);}}
  @Override void fetch(String id,boolean save,java.util.function.LongConsumer progress,Consumer<android.net.Uri> done,Consumer<String> fail){progress.accept(-1);if(failCopy)fail.accept("Download failed");else{copies++;done.accept(android.net.Uri.parse("content://media/external/images/media/"+copies));}}
  @Override void remote(String value){ticket=value;}
 }
 @Test public void settingsRemainOpenAndReflectConfirmedState(){JSONObject[] state={Wire.object("background",true)};CaptureSettingsUi.settings(activity,state[0],true,(command,done)->{state[0]=Wire.object("background",command.optBoolean("value"));done.accept(state[0]);});Dialog d=ShadowDialog.getLatestDialog();CheckBox box=(CheckBox)text(d,"Background capture");box.performClick();assertTrue(d.isShowing());assertSame(d,ShadowDialog.getLatestDialog());assertFalse(((CheckBox)text(d,"Background capture")).isChecked());}
 @Test public void failedSettingRollsBackWithoutClosing(){CaptureSettingsUi.settings(activity,Wire.object("background",true),true,(c,done)->done.accept(null));Dialog d=ShadowDialog.getLatestDialog();text(d,"Background capture").performClick();assertTrue(d.isShowing());assertTrue(((CheckBox)text(d,"Background capture")).isChecked());}
 @Test public void clockOverlaysMenuWithoutReservedTopRow(){CaptureSettingsUi.settings(activity,new JSONObject(),true,(c,d)->d.accept(c));Dialog dialog=ShadowDialog.getLatestDialog();assertEquals(1,views(dialog).stream().filter(v->v instanceof CurvedClock).count());ScrollView scroll=(ScrollView)views(dialog).stream().filter(v->v instanceof ScrollView).findFirst().orElseThrow();assertEquals(0,((ViewGroup.MarginLayoutParams)scroll.getLayoutParams()).topMargin);CurvedClock clock=(CurvedClock)views(dialog).stream().filter(v->v instanceof CurvedClock).findFirst().orElseThrow();assertNull(clock.getBackground());assertFalse(clock.isClickable());}
 @Test public void deletingDetailRefreshesUnderlyingGallery(){gallery.open();Dialog parent=ShadowDialog.getLatestDialog();((View)text(parent,"IMG_one.jpg").getParent()).performClick();Dialog detail=ShadowDialog.getLatestDialog();text(detail,"Delete from phone").performClick();Dialog confirm=ShadowDialog.getLatestDialog();text(confirm,"Delete").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(parent.isShowing());assertFalse(detail.isShowing());assertFalse(has(parent,"IMG_one.jpg"));assertTrue(media.listCalls>=2);assertEquals("Deleted from phone",ShadowToast.getTextOfLatestToast());}
 @Test public void multiSelectionSharesBothAndLayoutStaysOpen(){gallery.open();Dialog parent=ShadowDialog.getLatestDialog();((View)text(parent,"IMG_one.jpg").getParent()).performLongClick();((View)text(parent,"▶ VID_two.mp4").getParent()).performClick();assertTrue(has(parent,"Selected: 2"));text(parent,"Share on phone").performClick();assertEquals("share",media.last.optString("op"));assertEquals(2,media.last.optJSONArray("ids").length());assertEquals("share-ticket",media.ticket);text(parent,"Clear selection").performClick();text(parent,"View: list / tiles").performClick();Dialog picker=ShadowDialog.getLatestDialog();text(picker,"List").performClick();assertTrue(parent.isShowing());assertFalse(picker.isShowing());assertFalse(activity.getPreferences(0).getBoolean("gallery_tiles",true));}
 @Test public void accessibilityCaptureCanStopVideoWithoutChangingTouchSnapshot(){AtomicInteger touch=new AtomicInteger(),gesture=new AtomicInteger();IconButton b=new IconButton(activity,"photo","Capture",touch::incrementAndGet);b.accessibilityAction(()->{gesture.incrementAndGet();return true;});assertEquals("android.widget.Button",b.getAccessibilityClassName());assertTrue(b.performAccessibilityAction(AccessibilityNodeInfo.ACTION_CLICK,null));assertEquals(1,gesture.get());assertEquals(0,touch.get());b.performClick();assertEquals(1,touch.get());b.setEnabled(false);assertFalse(b.performAccessibilityAction(AccessibilityNodeInfo.ACTION_CLICK,null));}
 @Test public void englishIsFallbackAndRussianOnlyForPrimaryRussian(){for(String locale:new String[]{"en-rUS","de-rDE","fr-rFR","ru-rRU"}){RuntimeEnvironment.setQualifiers(locale+"-w240dp-h240dp-round-xhdpi");Strings.init(activity);assertEquals(locale.startsWith("ru")?"Галерея":"Gallery",Strings.tr(com.daniil.wristlens.shared.R.string.wl_187));assertEquals(locale.startsWith("ru")?"Фото сохранено":"Photo saved",Strings.message("Фото сохранено"));}}
 @Test public void downloadStartsInBackgroundAndKeepsDetailOpen(){gallery.open();Dialog parent=ShadowDialog.getLatestDialog();((View)text(parent,"IMG_one.jpg").getParent()).performClick();Dialog detail=ShadowDialog.getLatestDialog();text(detail,"Download to watch").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals("Download started",ShadowToast.getTextOfLatestToast());assertTrue(detail.isShowing());assertEquals(1,DownloadTestDispatch.enqueued.size());gallery.close();assertTrue(DownloadTestDispatch.cancelled.isEmpty());assertEquals(Downloads.QUEUED,Downloads.state(activity,"node","1").phase());}
 @Test public void batchDownloadQueuesAllSelectedFilesOnce(){gallery.open();Dialog d=ShadowDialog.getLatestDialog();((View)text(d,"IMG_one.jpg").getParent()).performLongClick();((View)text(d,"▶ VID_two.mp4").getParent()).performClick();text(d,"Download selected").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,DownloadTestDispatch.enqueued.size());assertEquals(2,Downloads.job(activity,Downloads.state(activity,"node","1").job()).optJSONArray("items").length());assertEquals("Download started",ShadowToast.getTextOfLatestToast());}
}
